[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --blue:#3861FB;--navy:#0D1421;--gray:#808A9D;--gray-light:#EFF2F5;
  --gray-bg:#F8FAFD;--white:#fff;--green:#16c784;--red:#ea3943;
  --border:#EFF2F5;--radius:8px;--shadow:0 1px 3px rgba(0,0,0,.06);
  --font:'Inter',system-ui,-apple-system,sans-serif;
}
html{font-size:14px;-webkit-font-smoothing:antialiased}
body{font-family:var(--font);color:var(--navy);background:var(--gray-bg);line-height:1.5}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:none;background:none}
.container{max-width:1400px;margin:0 auto;padding:0 20px}

/* NAV */
.nav{background:var(--white);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:100}
.nav-inner{display:flex;align-items:center;height:56px;gap:24px}
.nav-logo{font-weight:800;font-size:1.15rem;color:var(--blue);white-space:nowrap;display:flex;align-items:center;gap:6px}
.nav-logo svg{width:24px;height:24px}
.nav-links{display:flex;gap:4px;flex:1}
.nav-links a{padding:8px 14px;border-radius:var(--radius);font-weight:500;font-size:.9rem;color:var(--navy);transition:background .15s}
.nav-links a:hover{background:var(--gray-light);color:var(--blue)}
.nav-cta{display:flex;gap:8px;margin-left:auto}
.btn{padding:8px 18px;border-radius:var(--radius);font-weight:600;font-size:.85rem;transition:all .15s}
.btn-ghost{color:var(--blue)}
.btn-ghost:hover{background:rgba(56,97,251,.08)}
.btn-primary{background:var(--blue);color:#fff}
.btn-primary:hover{background:#2d4fd9}

/* TOP METRICS BAR */
.metrics-bar{background:var(--white);border-bottom:1px solid var(--border);padding:10px 0;font-size:.82rem}
.metrics-bar .container{display:flex;gap:24px;align-items:center;flex-wrap:wrap}
.metric-item{display:flex;align-items:center;gap:6px;white-space:nowrap}
.metric-label{color:var(--gray)}
.metric-value{font-weight:600;font-variant-numeric:tabular-nums}
.metric-change{font-weight:600;font-variant-numeric:tabular-nums}
.metric-change.up{color:var(--green)}
.metric-change.down{color:var(--red)}
.metric-badge{display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border-radius:4px;font-size:.75rem;font-weight:600}
.metric-badge.neutral{background:#FFF3CD;color:#856404}
.metric-badge.btc{background:#FFF0E6;color:#C45A00}
.fear-meter{width:40px;height:6px;background:#e0e0e0;border-radius:3px;overflow:hidden;display:inline-block;vertical-align:middle;margin-left:4px}
.fear-meter-fill{height:100%;border-radius:3px;background:linear-gradient(90deg,var(--red),#f5a623,var(--green));width:57%}

/* PROMO BANNER */
.promo-banner{background:linear-gradient(135deg,#1a1f36 0%,#2d3561 100%);padding:12px 0;position:relative;overflow:hidden}
.promo-slides{display:flex;transition:transform .5s ease}
.promo-slide{min-width:100%;text-align:center;color:#fff;font-size:.88rem;font-weight:500;padding:0 40px}
.promo-slide a{color:#7EB5FF;text-decoration:underline}
.promo-nav{position:absolute;top:50%;transform:translateY(-50%);background:rgba(255,255,255,.15);border:none;color:#fff;width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:1rem;transition:background .2s}
.promo-nav:hover{background:rgba(255,255,255,.3)}
.promo-nav.prev{left:12px}
.promo-nav.next{right:12px}
.promo-dots{display:flex;justify-content:center;gap:6px;margin-top:6px}
.promo-dot{width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,.3);cursor:pointer;transition:background .2s}
.promo-dot.active{background:#fff}

/* AI ALERTS BAR */
.ai-bar{background:var(--white);border-bottom:1px solid var(--border);padding:14px 0}
.ai-bar-inner{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.ai-topic{display:flex;align-items:center;gap:8px;background:linear-gradient(135deg,#EEF2FF,#F3E8FF);padding:8px 16px;border-radius:20px;font-size:.85rem;font-weight:500;flex-shrink:0}
.ai-topic svg{width:16px;height:16px;color:var(--blue)}
.ai-suggestions{display:flex;gap:8px;flex-wrap:wrap;flex:1}
.ai-chip{padding:6px 14px;border-radius:20px;border:1px solid var(--border);font-size:.78rem;color:var(--gray);background:var(--white);transition:all .15s;cursor:pointer;white-space:nowrap}
.ai-chip:hover{border-color:var(--blue);color:var(--blue);background:rgba(56,97,251,.04)}

/* MAIN CONTENT */
.main{padding:20px 0 40px}

/* FILTER TABS */
.filter-section{margin-bottom:16px}
.filter-row{display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap}
.filter-tabs{display:flex;gap:4px;flex-wrap:wrap}
.filter-tab{padding:7px 16px;border-radius:var(--radius);font-size:.85rem;font-weight:500;color:var(--gray);cursor:pointer;transition:all .15s;border:1px solid transparent}
.filter-tab:hover{color:var(--navy);background:var(--gray-light)}
.filter-tab.active{background:var(--blue);color:#fff;border-color:var(--blue)}
.network-tabs .filter-tab.active{background:var(--navy);color:#fff;border-color:var(--navy)}
.filter-label{font-size:.78rem;font-weight:600;color:var(--gray);text-transform:uppercase;letter-spacing:.5px;margin-right:4px}

/* INDEX ROW */
.index-row{background:linear-gradient(135deg,#FAFBFF,#F0F3FF);border:1px solid #E0E7FF;border-radius:var(--radius);padding:12px 20px;margin-bottom:16px;display:flex;align-items:center;gap:24px;flex-wrap:wrap}
.index-name{font-weight:600;font-size:.9rem;color:var(--navy);display:flex;align-items:center;gap:8px}
.index-name span{font-size:.75rem;color:var(--gray);font-weight:400}
.index-price{font-weight:700;font-size:1rem;font-variant-numeric:tabular-nums}
.index-changes{display:flex;gap:16px}
.index-change{font-size:.82rem;font-weight:600;font-variant-numeric:tabular-nums}

/* TABLE CONTROLS */
.table-controls{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;flex-wrap:wrap;gap:8px}
.table-controls-left{display:flex;gap:8px;align-items:center}
.control-btn{display:flex;align-items:center;gap:6px;padding:7px 14px;border-radius:var(--radius);font-size:.82rem;font-weight:500;color:var(--navy);border:1px solid var(--border);background:var(--white);transition:all .15s}
.control-btn:hover{border-color:var(--blue);color:var(--blue)}
.control-btn.active{border-color:var(--blue);color:var(--blue);background:rgba(56,97,251,.04)}
.control-btn svg{width:14px;height:14px}
.sort-active{font-weight:600;color:var(--blue);border-color:var(--blue)}
.table-controls-right{display:flex;gap:8px}

/* COLUMNS DROPDOWN */
.dropdown-wrap{position:relative}
.dropdown-panel{position:absolute;top:calc(100% + 4px);right:0;background:var(--white);border:1px solid var(--border);border-radius:var(--radius);box-shadow:0 8px 24px rgba(0,0,0,.12);padding:12px;min-width:220px;z-index:50;display:none}
.dropdown-panel.open{display:block}
.dropdown-panel label{display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:4px;font-size:.82rem;cursor:pointer;transition:background .1s}
.dropdown-panel label:hover{background:var(--gray-light)}
.dropdown-panel input[type="checkbox"]{accent-color:var(--blue);width:16px;height:16px}

/* FILTERS PANEL */
.filters-panel{background:var(--white);border:1px solid var(--border);border-radius:var(--radius);padding:16px 20px;margin-bottom:12px;display:none;gap:16px;flex-wrap:wrap}
.filters-panel.open{display:flex}
.filter-group{display:flex;flex-direction:column;gap:4px}
.filter-group-label{font-size:.75rem;font-weight:600;color:var(--gray);text-transform:uppercase;letter-spacing:.5px}
.filter-group select,.filter-group input{padding:6px 10px;border:1px solid var(--border);border-radius:6px;font-size:.82rem;font-family:var(--font);min-width:140px}
.filter-group select:focus,.filter-group input:focus{outline:none;border-color:var(--blue)}
.filter-actions{display:flex;align-items:flex-end;gap:8px}
.btn-sm{padding:6px 14px;border-radius:6px;font-size:.8rem;font-weight:600}

/* TABLE */
.table-wrap{background:var(--white);border-radius:var(--radius);border:1px solid var(--border);overflow-x:auto;box-shadow:var(--shadow)}
table{width:100%;border-collapse:collapse;min-width:1100px}
thead{position:sticky;top:0;z-index:10}
th{background:var(--gray-bg);padding:10px 12px;font-size:.75rem;font-weight:600;color:var(--gray);text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid var(--border);white-space:nowrap;cursor:pointer;user-select:none;transition:color .15s}
th:hover{color:var(--navy)}
th.text-right,td.text-right{text-align:right}
th.text-left,td.text-left{text-align:left}
td{padding:10px 12px;border-bottom:1px solid var(--border);font-size:.85rem;font-variant-numeric:tabular-nums;white-space:nowrap;vertical-align:middle}
tr:hover{background:rgba(56,97,251,.02)}
tr:last-child td{border-bottom:none}
.coin-name-cell{display:flex;align-items:center;gap:10px}
.coin-icon{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:.7rem;color:#fff;flex-shrink:0}
.coin-info{display:flex;flex-direction:column}
.coin-name{font-weight:600;font-size:.85rem;color:var(--navy)}
.coin-symbol{font-size:.75rem;color:var(--gray)}
.star-btn{color:#D1D5DB;cursor:pointer;transition:color .15s;font-size:1rem}
.star-btn:hover,.star-btn.active{color:#F59E0B}
.pct-up{color:var(--green);font-weight:500}
.pct-down{color:var(--red);font-weight:500}
.pct-neutral{color:var(--gray);font-weight:500}
.sparkline{width:120px;height:36px}
.volume-bar{display:flex;flex-direction:column;gap:2px}
.volume-main{font-weight:500}
.volume-sub{font-size:.72rem;color:var(--gray)}

/* PAGINATION */
.pagination{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;flex-wrap:wrap;gap:8px}
.pagination-info{font-size:.82rem;color:var(--gray)}
.pagination-pages{display:flex;gap:4px}
.page-btn{width:32px;height:32px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:500;color:var(--gray);border:1px solid transparent;transition:all .15s;cursor:pointer;background:none}
.page-btn:hover{background:var(--gray-light);color:var(--navy)}
.page-btn.active{background:var(--blue);color:#fff;border-color:var(--blue)}
.page-btn.ellipsis{cursor:default;border:none}
.page-btn.ellipsis:hover{background:none}

/* MARKET SUMMARY */
.market-summary{background:var(--white);border:1px solid var(--border);border-radius:var(--radius);padding:24px;margin-top:24px;box-shadow:var(--shadow)}
.market-summary h3{font-size:1rem;font-weight:700;margin-bottom:12px}
.market-summary p{font-size:.88rem;color:#333;line-height:1.7}
.market-summary strong{color:var(--navy)}
.read-more-btn{color:var(--blue);font-weight:600;font-size:.85rem;cursor:pointer;margin-top:8px;display:inline-flex;align-items:center;gap:4px;transition:opacity .15s}
.read-more-btn:hover{opacity:.8}
.read-more-content{display:none;margin-top:12px;padding-top:12px;border-top:1px solid var(--border)}
.read-more-content.open{display:block}

/* INFO CONTENT */
.info-content{margin-top:32px;display:grid;grid-template-columns:1fr 1fr;gap:24px}
.info-card{background:var(--white);border:1px solid var(--border);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow)}
.info-card h3{font-size:.95rem;font-weight:700;margin-bottom:8px;color:var(--navy)}
.info-card p{font-size:.85rem;color:#555;line-height:1.7}

/* FOOTER */
.footer{background:var(--navy);color:#fff;margin-top:48px;padding:48px 0 24px}
.footer-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:32px;margin-bottom:32px}
.footer-col h4{font-size:.82rem;font-weight:600;text-transform:uppercase;letter-spacing:.5px;margin-bottom:12px;color:var(--gray)}
.footer-col a{display:block;font-size:.85rem;color:#B0B8C8;padding:3px 0;transition:color .15s}
.footer-col a:hover{color:#fff}
.footer-bottom{border-top:1px solid #283044;padding-top:20px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px}
.footer-bottom p{font-size:.8rem;color:var(--gray)}
.footer-socials{display:flex;gap:12px}
.footer-socials a{color:var(--gray);transition:color .15s}
.footer-socials a:hover{color:#fff}

/* RESPONSIVE */
@media(max-width:900px){
  .nav-links{display:none}
  .info-content{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:repeat(2,1fr)}
  .metrics-bar .container{gap:12px}
  .ai-suggestions{overflow-x:auto;flex-wrap:nowrap;padding-bottom:4px}
}
@media(max-width:600px){
  .footer-grid{grid-template-columns:1fr}
  .index-row{flex-direction:column;align-items:flex-start;gap:8px}
}
</style>
</head>
<body>

<!-- NAVIGATION -->
<nav class="nav">
<div class="container nav-inner">
  <a href="/" class="nav-logo">
    <svg viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" stroke="#3861FB" stroke-width="2.5"/><path d="M8 12h8M12 8v8" stroke="#3861FB" stroke-width="2.5" stroke-linecap="round"/></svg>
