// Watchlist state
const watchlist = new Set();

// ── FORMAT HELPERS ──
function fmtPrice(p){
  if(p>=1) return '$'+p.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(p>=0.01) return '$'+p.toFixed(4);
  if(p>=0.0001) return '$'+p.toFixed(6);
  if(p>=0.000001) return '$'+p.toFixed(8);
  return '$'+p.toExponential(2);
}
function fmtMcap(v){
  if(v>=1e12) return '$'+(v/1e12).toFixed(2)+'T';
  if(v>=1e9) return '$'+(v/1e9).toFixed(2)+'B';
  if(v>=1e6) return '$'+(v/1e6).toFixed(2)+'M';
  return '$'+v.toLocaleString('en-US');
}
function fmtPct(v){
  const cls = v>0?'pct-up':v<0?'pct-down':'pct-neutral';
  const sign = v>0?'+':'';
  return `<span class="${cls}">${sign}${v.toFixed(2)}%</span>`;
}

// ── SPARKLINE SVG ──
function genSparkline(d7,clr){
  const pts = [];
  const n = 20;
  let val = 50;
  const trend = d7 / 100;
  for(let i=0;i<n;i++){
    val += (Math.random()-0.45)*6 + trend*3;
    val = Math.max(5,Math.min(95,val));
    pts.push(val);
  }
  // ensure end reflects direction
  if(d7>0) pts[n-1]=Math.max(pts[n-1],65);
  else if(d7<0) pts[n-1]=Math.min(pts[n-1],35);

  const w=120,h=36,pad=2;
  const xs=pts.map((_,i)=>pad+(i/(n-1))*(w-2*pad));
  const ys=pts.map(v=>pad+(1-v/100)*(h-2*pad));
  let path='M'+xs[0]+','+ys[0];
  for(let i=1;i<n;i++) path+=' L'+xs[i]+','+ys[i];
  const color=d7>=0?'var(--green)':'var(--red)';
  // gradient fill
  const gid='sg'+Math.random().toString(36).substr(2,6);
  return `<svg class="sparkline" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">
    <defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="${color}" stop-opacity="0.15"/>
      <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
    </linearGradient></defs>
    <path d="${path} L${xs[n-1]},${h} L${xs[0]},${h} Z" fill="url(#${gid})" stroke="none"/>
    <path d="${path}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

// ── TABLE RENDERING ──
let currentSort='mc';
let sortDir='desc';
let activeNetwork='all';
let activeCategory='top';
let activePage=1;
let filterMinMcap=0;
let filterMaxMcap=Infinity;
let filterChange='';

function getFilteredData(){
  let data=[...CRYPTOS];
  if(activeNetwork!=='all') data=data.filter(c=>c.net===activeNetwork);
  if(activeCategory==='watchlist') data=data.filter(c=>watchlist.has(c.s));
  else if(activeCategory!=='top'&&activeCategory!=='more') data=data.filter(c=>c.cat.includes(activeCategory));
  if(filterMinMcap>0) data=data.filter(c=>c.mc>=filterMinMcap);
  if(filterMaxMcap<Infinity) data=data.filter(c=>c.mc<=filterMaxMcap);
  if(filterChange==='up') data=data.filter(c=>c.h24>0);
  else if(filterChange==='down') data=data.filter(c=>c.h24<0);
  // sort
  const key=currentSort==='mc'?'mc':'v';
  data.sort((a,b)=>sortDir==='desc'?b[key]-a[key]:a[key]-b[key]);
  return data;
}

function renderTable(){
  const data=getFilteredData();
  const tbody=document.getElementById('tableBody');
  const visibleCols={};
  document.querySelectorAll('#columnsPanel input').forEach(cb=>{
    visibleCols[cb.dataset.col]=cb.checked;
  });

  let html='';
  data.forEach((c,i)=>{
    const starred=watchlist.has(c.s)?'active':'';
    html+=`<tr>
      <td><span class="star-btn ${starred}" data-sym="${c.s}" onclick="toggleStar(this)">&#9733;</span></td>
      <td class="text-left" style="color:var(--gray);font-weight:500">${i+1}</td>
      <td class="text-left">
        <div class="coin-name-cell">
          <div class="coin-icon" style="background:${c.clr}">${c.s.substring(0,2)}</div>
          <div class="coin-info">
            <span class="coin-name">${c.n}</span>
            <span class="coin-symbol">${c.s}</span>
          </div>
        </div>
      </td>
      ${visibleCols.price!==false?`<td class="text-right" style="font-weight:600">${fmtPrice(c.p)}</td>`:''}
      ${visibleCols['1h']!==false?`<td class="text-right">${fmtPct(c.h1)}</td>`:''}
      ${visibleCols['24h']!==false?`<td class="text-right">${fmtPct(c.h24)}</td>`:''}
      ${visibleCols['7d']!==false?`<td class="text-right">${fmtPct(c.d7)}</td>`:''}
      ${visibleCols.mcap!==false?`<td class="text-right">${fmtMcap(c.mc)}</td>`:''}
      ${visibleCols.vol!==false?`<td class="text-right"><div class="volume-bar"><span class="volume-main">${fmtMcap(c.v)}</span></div></td>`:''}
      ${visibleCols.supply!==false?`<td class="text-right" style="color:var(--gray)">${c.cs}</td>`:''}
      ${visibleCols.spark!==false?`<td class="text-right">${genSparkline(c.d7)}</td>`:''}
    </tr>`;
  });
  tbody.innerHTML=html;
  // Update column visibility in header
  const colMap={'price':3,'1h':4,'24h':5,'7d':6,'mcap':7,'vol':8,'supply':9,'spark':10};
  document.querySelectorAll('#cryptoTable thead th').forEach((th,idx)=>{
    for(const[k,v] of Object.entries(colMap)){
      if(idx===v) th.style.display=visibleCols[k]===false?'none':'';
    }
  });
  // update pagination info
  document.querySelector('.pagination-info').textContent=`Showing 1–${data.length} of 8,364 assets`;
}

