// ── FILTERS PANEL ──
function toggleFilters(){
  const panel=document.getElementById('filtersPanel');
  panel.classList.toggle('open');
  document.getElementById('filtersBtn').classList.toggle('active');
}
function parseMcapVal(s){
  s=s.replace(/[$,\s]/g,'').toUpperCase();
  if(s.endsWith('T')) return parseFloat(s)*1e12;
  if(s.endsWith('B')) return parseFloat(s)*1e9;
  if(s.endsWith('M')) return parseFloat(s)*1e6;
  return parseFloat(s)||0;
}
function applyFilters(){
  const min=document.getElementById('filterMinMcap').value;
  const max=document.getElementById('filterMaxMcap').value;
  filterMinMcap=min?parseMcapVal(min):0;
  filterMaxMcap=max?parseMcapVal(max):Infinity;
  filterChange=document.getElementById('filterChange').value;
  renderTable();
}
function clearFilters(){
  document.getElementById('filterMinMcap').value='';
  document.getElementById('filterMaxMcap').value='';
  document.getElementById('filterChange').value='';
  filterMinMcap=0;filterMaxMcap=Infinity;filterChange='';
  renderTable();
}

// ── PROMO CAROUSEL ──
let promoIdx=0;
const slides=document.getElementById('promoSlides');
const slideCount=slides.children.length;
const dotsEl=document.getElementById('promoDots');
for(let i=0;i<slideCount;i++){
  const d=document.createElement('span');
  d.className='promo-dot'+(i===0?' active':'');
  d.onclick=()=>goPromo(i);
  dotsEl.appendChild(d);
}
function goPromo(idx){
  promoIdx=idx;
  slides.style.transform=`translateX(-${promoIdx*100}%)`;
  document.querySelectorAll('.promo-dot').forEach((d,i)=>d.classList.toggle('active',i===promoIdx));
}
function movePromo(dir){
  goPromo((promoIdx+dir+slideCount)%slideCount);
}
setInterval(()=>movePromo(1),5000);

// ── READ MORE ──
function toggleReadMore(){
  const content=document.getElementById('readMoreContent');
  const arrow=document.getElementById('readMoreArrow');
  content.classList.toggle('open');
  arrow.innerHTML=content.classList.contains('open')?'&#9652;':'&#9662;';
  document.querySelector('.read-more-btn').firstChild.textContent=content.classList.contains('open')?'Read Less ':'Read More ';
}

// ── PAGINATION ──
document.getElementById('paginationPages').addEventListener('click',e=>{
